package main

import "testing"

func TestPriorityOrder(t *testing.T) {
	q := NewStablePriorityQueue()
	q.Push(5, "low")
	q.Push(1, "high")
	q.Push(3, "mid")
	got := []string{q.Pop(), q.Pop(), q.Pop()}
	want := []string{"high", "mid", "low"}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("got %v, want %v", got, want)
		}
	}
}

func TestEqualPriorityIsFifoAcrossManyItems(t *testing.T) {
	q := NewStablePriorityQueue()
	for i := 0; i < 20; i++ {
		q.Push(1, string(rune('a'+i)))
	}
	for i := 0; i < 20; i++ {
		got := q.Pop()
		want := string(rune('a' + i))
		if got != want {
			t.Fatalf("pop %d: got %q, want %q", i, got, want)
		}
	}
}

