package main

import "container/heap"

type Item struct {
	Priority int
	Order    int
	Value    string
}

type priorityQueue []*Item

func (pq priorityQueue) Len() int { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool {
	if pq[i].Priority != pq[j].Priority {
		return pq[i].Priority < pq[j].Priority
	}
	return pq[i].Order < pq[j].Order
}
func (pq priorityQueue) Swap(i, j int) { pq[i], pq[j] = pq[j], pq[i] }
func (pq *priorityQueue) Push(x any)   { *pq = append(*pq, x.(*Item)) }
func (pq *priorityQueue) Pop() any {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

type StablePriorityQueue struct {
	heap    priorityQueue
	counter int
}

func NewStablePriorityQueue() *StablePriorityQueue {
	return &StablePriorityQueue{}
}

func (q *StablePriorityQueue) Push(priority int, value string) {
	heap.Push(&q.heap, &Item{Priority: priority, Order: q.counter, Value: value})
	q.counter++
}

func (q *StablePriorityQueue) Pop() string {
	return heap.Pop(&q.heap).(*Item).Value
}

func (q *StablePriorityQueue) Len() int {
	return q.heap.Len()
}

